-- ============================================================================
--  Pacientes atendidos 2026 -> tabla users (rol paciente)
--  Origen: subir base pacientes atendidos 2026.xlsx (Hoja1)
--  Filas del archivo: 348247  |  Documentos únicos: 102328
--
--  Mapeo:  identificacion -> Numero_D   apellido_1 -> Apellido1
--          apellido_2 -> apellido2      nombre -> name
--          telefono_1 -> Telefono1      EPS -> Eps      rol = 'paciente'
--          tipo_Docu = 'Cédula de Ciudadanía'
--  El resto de campos queda en NULL.
--
--  NO duplica: solo inserta los documentos que todavía no están en users
--  (compara Numero_D sin espacios ni mayúsculas). Se puede ejecutar más de
--  una vez sin crear repetidos.
--
--  CÓMO APLICARLO EN CPANEL:
--    1. Copia de seguridad de la base.
--    2. phpMyAdmin > base (uoxclxvl_tools) > Importar > este archivo
--       (es grande: use "Importar", no la pestaña SQL).
-- ============================================================================

SET NAMES utf8mb4;

DROP TABLE IF EXISTS `tmp_pacientes_2026`;
CREATE TABLE `tmp_pacientes_2026` (
  `Numero_D` varchar(20) NOT NULL,
  `name` varchar(255) NOT NULL,
  `Apellido1` varchar(50) NULL,
  `apellido2` varchar(50) NULL,
  `Telefono1` varchar(50) NULL,
  `Eps` varchar(120) NULL,
  PRIMARY KEY (`Numero_D`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- Inserta solo los documentos que no existen ya en users.
SELECT s.`name`, 'Cédula de Ciudadanía', s.`Numero_D`, s.`Apellido1`, s.`apellido2`, s.`Telefono1`, s.`Eps`, 'paciente'
FROM `tmp_pacientes_2026` s
LEFT JOIN `users` u ON UPPER(TRIM(u.`Numero_D`)) = s.`Numero_D`
WHERE u.`id` IS NULL;

SELECT ROW_COUNT() AS pacientes_insertados;

DROP TABLE IF EXISTS `tmp_pacientes_2026`;
